import{_ as t,c as s,o as i,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"周易經傳集解卷四","description":"周易經傳集解 - 周易經傳集解卷四","frontmatter":{"title":"周易經傳集解卷四","description":"周易經傳集解 - 周易經傳集解卷四"},"headers":[],"relativePath":"classics/jingchuan-jijie/005.md","filePath":"classics/jingchuan-jijie/005.md"}'),r={name:"classics/jingchuan-jijie/005.md"};function c(o,a,l,d,p,j){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易經傳集解卷四",tabindex:"-1"},[n("周易經傳集解卷四 "),e("a",{class:"header-anchor",href:"#周易經傳集解卷四","aria-label":"Permalink to “周易經傳集解卷四”"},"​")],-1),e("p",null,"欽定四庫全書周易經傳集解師比卷四 ​宋林栗撰序卦曰：「訟必有眾起，故受以師。」師者，眾也。「師」，訟之變也。自訟而師，下坎不動，上乾變坤而成卦也。乾自需而訟，至於上九，反入於淵，是以變而為坤。夫民有所不得其平，而後至於訟。訟而有以正之，則始乎訟而卒於無訟，是之謂治世。及其亂也，以訟濟訟，相激為深而己。有冤而無所訴，有訴而無所直，疾視其長上而幸其危亡，其不起而為亂者，未之有也。是以秦之將亡，其民皆欲剚刃於其長吏，而後干戈之事興矣。故曰：「訟必有眾起，故受之以師。」師者，眾也。坤三為眾，又合坎之二陰，斯為大眾矣。而坎中一陽實居下卦之中，五陰雖眾，莫能相攝，其勢必歸於一陽。一陽在下而為眾陰之主，非行師之義而何以當之哉？是以謂之師也。師：貞，大人吉，無咎。彖曰：「師」，眾也；「貞」，正也。能以眾正，可以王矣。剛中而應，行險而順，以此毒而天下，而民從之，吉又何咎矣？上坤下坎成卦曰「師」者，坎為險，震為動，坤為眾，為順。以險動眾，師旅之事也；以順行險，師旅之義也。夫兵，兇器也；戰，危事也。聖人豈得已而用之哉？將以誅除暴亂，保衛生靈，順天之心，因民之慾，興動大眾，而人不以為勞；驅之於萬死一生之地，而人不以為怨，凡以其順動之故也。然十人之聚，必聽其雄；百夫之群，必建其長。聚大眾而無以正之，未見敵而先自敗矣。故曰：「師貞。」貞，正也，政令之所自出也。五陰而一陽，則一陽為之正也。一陽而於五陰之正，號令賞罰，莫敢不從。位宜在上，而反居於下，何也？師，帥之義也。有君在上，而帥得專之，雖君命有所不受，應其義矣。古者諸侯或七十里，或五十里，大者不過百里，行軍用師，未嘗不躬親之。惟王者之師，則命將統之，王不親行也。故曰：「大人吉。」大人，謂五也。子曰：「師，眾也。貞，正也。能以眾正，可以王矣。」傳曰：「師能左右之曰以。」眾之所奉以為正，而我能以之，不曰「大人」乎？古易諸家皆作「大」，自王弼以來本多作「丈夫」之「丈」。九二有正眾之才，而屈下為其君。六五以天下之眾，而委聽於其臣。殺伐果敢，而上無猜疑之端；威權假人，而下無驕恣之漸，夫何往而不濟？故曰「吉」，又曰「無咎」。子曰：「剛中而應，行險而順，以此毒天下而民從之，吉又何咎矣？」剛而得中，志應於上，二之所以「吉無咎」也。行天下之險，而順天下之心，五之所以「吉無咎」也。二爻之辭俱言之矣。或曰：震居坎中，故曰「行險」，而以六五當之，何也？曰：「師」之二五，相應者也。二之行險，五之命也。金石草木，莫不有毒，平居畏忌，無所不至，而疾病用之。兵之除害，猶治疾也。聚天下不義之徒，授之以不仁之器，而教之以殺人之事，以至仁伐至不仁，猶有血流漂杵之禍，夫是故謂之「毒」。以毒被天下，宜其怨苦，然而民樂從之者，順其心而除其害也。應天順人，吉又何咎哉？象曰：地中有水，「師」，君子以容民畜眾。「地」者，「坤」也；「水」者，「坎」也。地無所不容，水無乎不在，故「君子以容民畜眾」象之。「地中有水」，水之聚也。三軍六師，民之聚也。君子之聚民，如地中之畜水，則無流散奔衝之患矣。卦言師眾，本取諸「坤」，而大象則取諸「坎」，其歸一也。雜卦曰：「師，憂也。」「坎」之一陽為五陰之主，故有憂象，「坎」為憂故也。是故「師」之六爻，皆取憂懼之義焉。憂之如何？興天下之眾，而行天下之險，是其所以憂也；居人臣之位，而有天下之權，是其所以憂也。夫九二者，「師」之主也。二在憂懼之中，而諸爻欲無憂懼，得乎哉？是故初六有「失律」之憂，六三有「無功」之憂，六四有「失常」之憂，六五有「不當」之憂，上六有「亂邦」之憂。至於諸爻言「吉」，必曰「無咎」，其憂之也至矣。初六：師出以律，否臧，兇。象曰：「師出以律」，失律兇也。初六，坎也，以陰居剛，而在一卦之下，上無其應，而承於九二之震，故曰：「師出以律，否臧兇。」坎為律，震為出。古者出師，授之同律，所以整軍而經武也。在師之初，有出師以律之象。然以六居之，未必能持律也。四陰皆體「坤」居前而順九二之命，見危臨難，有不敢避。獨初六體「坎」而居其後，故有「否臧」之兇。「臧」言「律」也，「否」言失也。出師之初而失其律，「兇」可知也。或曰：以「律」訓「臧」，未聞前詁。曰：「臧」之言善也，善持律之謂也。得律為臧，失律為否，復何疑乎？師之初六，後軍之象也。後軍不整，師之通患也。使初而非陰，則師之象毀矣。及其為陰也，又有「失律」之憂。故聖人兩著其辭，以明得失之未可知，而憂懼之不敢忘也。子曰：「師出以律，失律兇也。」「否臧」之義，明白如此，而古今諸儒不勝異說，惟左氏傳為得之。曰：執事順成為臧，逆為否。否，逋靡反。或曰：「諸儒言律，或以為律法之律，或以為吹律之律，二者將安折中？」曰：「法律本於吹律，律起於黃鐘。黃鐘，坎也。古者斷竹為律，吹中聲以驗氣候，輕重長短，毫釐不差，度量權衡，於此而取則焉。是以後世法令通謂之律，取其無差忒也。」今此言「否臧之兇」，直謂法律爾，非謂吹律以聽軍聲也。若謂吹律以聽軍聲，一樂師之職耳。世無師曠，戰勝攻取，固自若也，何以言其「兇」乎？爾雅曰：「坎，律，銓也。」郭璞注曰：「易坎卦主法，法律皆所以銓量輕重。」蓋得之矣。九二：在師，中，吉，無咎。王三錫命。象曰：「在師中吉」，承天寵也。「王三錫命」，懷萬邦也。九二，震也。以陽居柔，而在下卦之中，應乎六五之「坤」，而為群陰之主，故曰「在師」。師，眾也。「坤」為眾，為順；震為長，為動。動而順，剛中而應，故曰：「中吉，無咎，王三錫命。」一陽居下，而為五陰之主，六五聽之，群陰順之，不在師而在國，則權臣之象矣。在師而不得中，未可以言吉。稟命則不畏，專命則不臣，專稟之貴乎中也。猛則失恩，寬則失威，寬威之貴乎中也。在師而得中，是以「吉」而「無咎」也。象所謂「師正吉無咎」是也。「王」，謂六五也。自五至二，所歷三爻，三錫命也。將帥而師，而王之錫命至於再三，所以昭寵渥而重其權也。夫為將者，所有之師，君之民也；所行之賞罰，君之柄也。君與之民，必與之柄。可賞而賞，可罰而罰，可誅而誅，可赦而赦，百萬之眾，莫敢不從，所恃者君命也。君無錫命，跬步不可行矣。是以古者遣帥推轂，而命之曰：「閫外之事，將軍主之。」猶以為未也，而至於再，至於三，斯可以信其恩威，而令其下矣。故曰：「在師中吉，承天寵也。」或曰：六五，坤也，而曰承天寵，何哉？曰：五者，天之位也。自天寵之，吉無咎矣。「王三錫命」，懷萬邦也。王之所以三錫命者，豈私於一師哉？所以懷來萬邦也。或曰：「寵一師而懷萬邦，其義安在？」曰：勤而見知，忠而見信，群臣諸侯莫不勸矣。不庭之方，不率之國，莫不懼矣。好我者莫不勸，惡我者莫不懼，懷來之術，有過於此者乎？六三：師或輿尸，兇。象曰：「師或輿尸」，大無功也。六三上體為「坤」，下體為「坎」，以陰居剛，而在下卦之上，上無其應，而乘乎九二之「震」，故曰：「師或輿尸，兇。」夫六五者，師之王也；九二者，師之帥也。六五體「坤」，「坤」為母；九二體震，震為長男。初六、六三體坎，「坎」為中男；六四體「艮」，艮為少男。以九二剛中之才，有六五柔上之應，憑冢嗣之貴，居師帥之任，「坎」、「艮」諸男，莫不聽順，此其所以「吉」也。然母之於子，親而不尊，多愛而少威，雖以師帥之權付之長子，至於「艮坎」諸男，未必不使之分其任也，故「或」之。「或」之者，疑也。「輿」者，眾也。「屍」者，主也。三、四以「坎」「艮」而雜乎「坤」，「坤」為眾，故有「輿尸」之象。行軍用師而眾主之，則號令不一，人心不齊，甲可乙否，莫知適從，如是而不敗者，未之有也。所以然者，初六、六三不當其位，而四比於五，有愛季之嫌故也。子曰：「師或輿尸，大無功也。」師無統一，未戰先潰，勞民費財而無尺寸之功，固可以言兇矣。何必前徒倒戈，流血漂杵，然後謂之兇乎？程氏曰：「自古任將不專而致覆敗者，晉荀林父邲之戰、唐郭子儀相州之役是也。」六四：師左次，無咎。象曰：「左次，無咎」，未失常也。六四上體為「坤」，下體為「艮」，以陰居柔，而在上卦之下，下無其應，而承於六五之「坤」，故曰：「師左次，無咎。」「坤」為順，「艮」為止，故有「左次」之象。老氏有言：「君子居則貴左，用兵則貴右。」偏將軍處左，上將軍處右，則左者不用之地，猶人之左手足不如右強也。不用之地，師之次舍也。「坤」為地，「艮」為山，「坎」為水。師之所次，右背山林，前左水澤。六四皆水而次，何也？曰：四之為「艮」，其體反也，故水澤為前左，而山陵平地為右背矣。以陰居剛，體乎「坤艮」，有「輿尸」之象，為其背山左水，有師次之象焉。是以變而言之也，止則如山，動則如雷，師之道也。故子曰：「左次無咎，未失常也。」若以陰居剛，則失其常矣。而「艮」體屍之，得為無咎乎哉？說者謂六四自度非才而不敢進，故得無咎。夫師帥者，社稷之司命，政之存亡，民之死生，於是乎在，可以非才而受其任乎？既受任矣，而「巽」儒不進，謂人曰：「我不能，雖復左次，其能免乎？」六五：田有禽，利執言，無咎。長子帥師，弟子輿尸，貞兇。象曰：「長子帥師」，以中行也。「弟子輿尸」，使不當也。「言」，當作「吉」，字之誤也。今改正。六五，「坤」也。以陰居剛，而在上卦之中，應乎九二之「震」，而乘乎六四。四，「坤」「艮」也，故曰：「田有禽，利執」。「坤」為地，故有田象。「艮」為黔喙之屬，故有禽象。「坤」之有「艮」，猶田之有「禽」也。古者搜苗獼狩，通謂之田，主於除害也。禽入我田，蹂踐禾稼，利在於執，不可縱舍。若快心縱舍，遊田無度，烈山澤而焚之，則獸不得安其居，人不得食其利矣。傳曰：「利人土地貨寶者，謂之貪兵。兵貪者敗。不得已而起者，謂之應兵。應兵者勝。」蠻夷滑夏，寇賊奸宄，不得已而用師，則「執田禽」之義也，故曰：「吉，無咎。」帝王之師，所以無敵於天下者，用此道也。夫說者沿襲訛誣，以執言為命辭，陋矣！夫動民以行不以法，應天以實不以名。克寬克仁，彰信兆民，東征西怨，南征北怨，豈區區執言而與之較哉？故彖言「大人吉，無咎」，而二、五之爻辭皆表而出之，不以為贅者，所以顯微而闡幽，不得不然爾。既曰「吉」，又曰「無咎」，何也？曰：「無咎者，善補過也。」夫以九二在下，而有震主之威，六五居尊，而行天下之險，宜其有咎矣。以其剛中而應，行險而順，故得無咎，豈非善補過之謂乎？故曰：「長子帥師，弟子輿尸，貞兇。」長子，「震」也。「弟子」，「坎」、「艮」也。應於九二，既有「長子帥師」之象；乘乎三四，復有「弟子輿尸」之憂。夫柔順者，五之所以為「貞」也。委任九二而責其成，不從中御，斯為善矣。然柔而無斷，則任不專一，二三其責，將有「輿尸」之兇矣。故子曰：「長子帥師，以中行也；弟子輿尸，使不當也。」夫長子也者，豈直謂其年長也哉？以其剛中而行健，當主帥之事，斯謂之長子矣，謂其有長人之材故也。苟或任所不當，十羊九牧，無所適從，欲無兇，得乎？或曰：卦以一陽為五陰之主，而六五謂之「大人」，何也？曰：五者，尊也；六者，柔也。以柔居尊，而九二為之應，吾能左右而使之，所謂能以眾者也。坤為順，震為動，坎為險，六五體坤而應乎正，去險難而就平地，所謂行險而順者也。謂之「大人」，不亦宜乎？世言用武之君，往往皆以勇略冠世，然後能之。此淺俗之論，非智識之談也。老子曰：「強大處下，柔弱處上。」夫惟不爭，故天下莫能與之爭。然則師之大人，以六居五，責成九二，以收撥亂之功，此韓信之所以為善將兵，而高帝之所以為善將將也。臧宮、馬武之徒所以鳴劍抵掌，而光武之所以閉關而謝質也。文帝勞亞夫之軍，軍門都尉曰：「軍中但聞將軍之令，不聞天子之詔。」自非文帝，有不能堪。以是知六五之為難能也。上六：大君有命，開國承家，小人勿用。象曰：「大君有命」，以正功也。「小人勿用」，必亂邦也。上六，「坤」也，以陰居柔，而在一卦之上，下無其應，而乘乎六五之「坤」，故曰：「大君有命，開國承家」。五居天位，故有「君命」之象。「坤」為上，為眾，為國邑，故有「開國成家」之象。方師之初，一陽在下而為之主，五陰莫不順聽者，「行師」之義也。及夫「開國承家」，而聽九二之制，則無君矣。故必「大君有命」，而後可以正其功。上居一卦之終，班師振旅，論功行賞之時也。故曰「小人勿用」。大者開國而為公侯，小者承家而為卿大夫。而小人之有功，賞之而勿用，此為國久長之計也。或曰：「謂之承家，則必繼世而後可乎？」非此之謂也。封之土而命之氏，使其子孫得以承襲，是之謂承家也。甚哉！小人之不可用也。譬之猶虎狼蝮蠍然，欲其不為民害，不可得也。聖人知其有功不可不賞也，故戒以「勿用」而已。或曰：小人之不可一日用也，而使之有功，何哉？曰：軍旅之事，使智使勇，使愚、使貪，古之道也，豈暇問君子小人哉？惟開國承家，然後得而審理之。武王克商，大封於廟，其詩曰「賚」，說者謂有周賚子也，言所以錫善人也。孔子曰：「周有大賚，善人是富。八百諸侯，三千虎士。」夫豈皆善人哉？其處之必有道矣。或曰：「功同賞異，則必悍然而不平，聖人將何以處之？」曰：象至不仁，封之有庳，天子使吏治其國，而納其貢賦焉，何憂其悍而縱其為暴也？光武懲高帝之事，不任功臣，得其道矣。或曰：師之諸爻，孰為君子？孰為小人？曰：九二、六四、上六，君子也。初六、六三，小人也。以九居二，德浮於位者也。六四、上六，德稱其位者也。初六、六三，則小人而乘君子之器也。初與三為坎，坎為小人故也。是以諸爻無咎，而初與三皆兇也。子曰：「大君有命，以正功也。小人勿用，必亂邦也。」夫大君者，以公天下為心者也。論功行賞，蔑不正矣。晉之王渾、王濬，隋之韓擒虎、賀若弼，所以爭功而不決者，二主之不君，從可知矣。若漢高帝有片言之喻，孰敢不聽乎哉？序卦曰：眾必有所比，故受之以比。比者，比也。比也者，親附之謂也。比之闕視師，比之象也。夫師、比，五陰而一陽，剛中而應，行險而順，均也。其所以為師為比者，二五之位尊卑之不同耳。其在於二，人臣之位也，可以行師而非立國之道也。其在於五，人君之位也，可以立國而非行師之義也。是故九二者，眾之所奉以為正也；九五者，眾之所戴以為君也。書曰：「萬夫之長，可以觀政。」九二之謂也。又曰：「眾非元后何戴？」九五之謂也。此「師」、「比」之所以異也。比：吉。原筮，元永貞，無咎。不寧方來，後夫兇。彖曰：比，輔也，下順從也。「原筮，元永貞，無咎」，以剛中也。「不寧方來」，上下應也。「後夫兇」，其道窮也。下坤上「坎」。成卦曰「比」者，「坤」為眾，為順，艮為止，「坎」為險。眾而止於險，「比」之勢也；順而止乎險，「比」之情也。「坎」、「坤」之中有「震」象焉，所以為「師」也；「坤」、「坎」之中有「艮」象焉，所以為「比」也。或曰：子於師之左次，田之有禽，皆以「艮」象言之矣。於此乃曰坎、坤有「震」而為師，坤、坎有艮而為比，何其相戾也？曰：易有四象，謂正體也。覆而取之，又四象也。一卦之彖，據正體而言之，及其在爻，至四而止矣。苟不覆之，則五、上二爻，將無所取；而三、四二爻，亦無以明反覆變化之義矣。故曰：「雜物撰得，辯是與非，則非其中爻不傋」，此之謂也。或曰：然則坤、坎為師，坎、坤為比，亦有其義乎？曰：「坎」也者，法度之所自出也。法度在下，而上順從之，所以為「師」也；法度在上，而下順從之，所以為「比」也。比：吉，原筮，元永貞。何謂也？曰：九五之謂也。受天下之比，如九五之正，可謂「吉」矣。天下之人，得其所「比」，如九三者，可謂「無咎」矣。故曰：「比，吉也。」「比」，輔也，下順從也。「輔」，當為「富」，傳寫誤耳。「順從」雲者，自四以下，皆「坤」象也。筮之為言，決疑之謂也。以陰比陽，以賤比貴，得其所以比則「吉」，失其所比則「兇」。吉凶之間，禍福之際，明者據之，取占筮之義也。原者，再也。猶原蠶、原廟之義也。元，始也。永，終也。貞，正也。筮其所以始終皆正，如九五者，可以無咎矣。夫以五陰而比一陽，其從之也，豈俟佔而後決哉？然而筮之至於再，何也？曰：去就之義大矣。賢者有所不知，而況於眾人乎？卦為二五、初四為吉，至於三上兩爻，有「匪人無首」之兇，不知「原筮」之故也。六三非陽也，而居於剛，自以為陽，而求配於上六，又介乎二四之間。二四舍三而此五，上六舍五而比二，吉凶之來，自取之也，可不審乎？九五體陽而居剛，六二、六四、上六體陰而居柔，如是而比，斯謂之「元永貞」者矣。故曰：原筮，元永貞，無咎，以剛中也。不寧方來，謂初六也。九五在上，六二在下，當比之時，而有不當其位者，非背叛之臣，即裔夷之君長也。初六一爻，最為僻遠，以陰居剛，不當其位，其四夷之國，不寧之方乎？初近於二，配於四，二四既得所比，初之從五，不佔而決矣。故曰：「不寧方來，上下應也」。後夫兇，謂上六也。夫也者，妻之所比也。君也者，臣之所比也。當比之時，九五中正，於臣民為君，於妻妾為夫。自四以下，莫不順之。所謂陽唱而陰和，男行而女隨也。上六獨乘於五，是後其夫也，其兇宜矣。孟子曰：「未有義而後其君者也」。或曰：三上配也，豈得反謂五為夫？曰：五陰一陽，陽居中正，天下一家之象也。天無二日，民無二王，上不比五而比三，是謂比之無首，比他人而後其夫也。上之所以比三者，為其居之可配，而不知其德之非夫，失「原筮」之道也。故曰：「後夫兇，其道窮也。」或曰：蒙之彖曰：初筮告，再三瀆。瀆則不告。明筮貴初而惡夫瀆也。今比之筮而貴乎再，是故將瀆之也歟？曰：夫言各有當也。書曰：「卜不習吉。」初筮之謂也。又曰：「一習吉。」原筮之謂也。蒙者之於「師」，亟問而弗志於心，其弗告之宜矣。臣之從君，婦之從夫，不可以苟合，苟合則離。思其始而圖其終，所以為久長之道也，何惡於原筮也哉？象曰：地上有水，「比」。先王以建萬國，親諸侯。「地」者，「坤」也；「水」者，「坎」也。天下之水，未有不附於地者。「地中有水」，水之聚也；「地上有水」，水之散也。水聚則為澤，及其散也，或為江河，或為溝瀆，而莫不比於地。民聚則為師，及其散也，或為方伯之國，或為子男之邦，而莫不比於王。此先王所以「建萬國，親諸侯」也。雜卦曰：「比樂師憂。」「坎」之一陽，為五陰之主，在「師」為憂，在「比」為樂，何也？曰：「師」、「比」以二五為主，「師」之二五不當其位，「比」之二五皆得其正故也。柔上而剛下，上下之所同憂也。陽尊而陰卑，尊卑之所同樂也。夫興師動眾，以毒天下，拯之塗炭之中，而措之衽席之上，豈不始於憂勤，而終於佚樂也哉？天下有王，生民有歸，於斯時也，可謂樂矣。是故「比」之諸爻，皆有佚樂之象。六二自內而吉，六四自外而亦吉，初六自他而亦吉，九五不誡而亦吉，惟六三、上六失其所比，有「匪人無首」之象也。當比之時，九五在上，順之者吉，逆之者兇；順之者安榮，逆之者危辱。自非反道背德之人，誰肯避吉而就兇，舍安榮而取危辱哉？此「比」之所以為樂也。故曰：「比者，比也。」其他爻則以上下相比明其義焉。初六：有孚比之，無咎。有孚盈缶，終來有他，吉。象曰：比之初六，「有他吉」也。初六，「坤」也，以陰居剛，而在一卦之下，上無其應，而承乎六二，二亦「坤」也，故曰：「有孚比之，無咎。」「坎」為有孚，謂九五也。以震而居坎中，群陰之所孚也。二應在五而比於初，四應在初而比於五，故初因二與四而得其所比焉，所謂「因不失其親」者也。所以然者，初體「坤」，「坤」為順，凡「比」之道，元永皆正，然後無咎。今初六最遠於五，不當其位，見五之有孚，而遠來比之，曷為無咎乎哉？孟子曰：「天無二日，民無二王。」詩云：「自西自東，自南自北，無思不服。」九五之謂也。初六避遠，因二與四而得所比，又何咎之有哉？故曰：「有孚盈缶，終來有他吉。」「坎」為「缶」，九五，「坎」中之陽，流而不盈者也。自四以下，皆「坤」象焉。以土製水，則其缶盈矣。「盈缶」也者，言其充實也。有諸中必形諸外，誠於此必著於彼。九五之孚，僅盈一缶，而有自他來比之者，初六是也。初為無咎，而五為吉矣。或曰：九五在上，無所不孚，而以盈缶言之，何也？曰：江出岷山，其源濫觴，極其所至，放乎四海。盈缶之孚，足以充塞乎天地之間矣。為人上者，患誠信之不充耳。苟能充之，何憂天下之不王，四夷之不服哉？子曰：「比之初六，有他吉也。」夫爻既言之矣，夫子又申言之，不幾於贅乎？曰：聖人之言簡而明，質而盡，學者顧未之思耳。今言易之家，皆於別爻求他吉之義，然後知聖人有味其言之也。蓋曰比之他吉，不在別爻，即初六是也。豈不簡而明、質而盡也哉？六二：比之自內，貞吉。象曰：「比之自內」，不自失也。六二，「坤」也。以陰居柔而在下卦之中，應乎九五之「震」，而承乎六三。三，「坤」「艮」也，故曰：「比之自內。」下卦為內，上卦為外，九五在上，六二自內而比之，故曰：「貞吉」。當比之時，二五中正，自內比之，可謂元永貞正，吉而無咎者矣。子曰：「比之自內，不自失也。」夫以陰柔為體乎「坤」，不憂其不順於五，而憂其自失於三也。能保其正，不自失於匪人，斯為吉矣。六三：比之匪人。象曰：「比之匪人」，不亦傷乎？六三上體為「艮」，下體為「坤」，以陰居剛而在下卦之上，上無其應，而介於二、四，二爻皆「坤」，而三又「坎」也。故曰：「比之匪人。」「匪人」者，非所比而比焉者也。二以其中，四以其近，皆獲「比」於五矣。獨上六後夫，而與三為背，謂之「匪人」，不亦宜乎？陽為貴，陰為賤。賤者，比人者也。貴者，比於人者也。陽為賢，陰為不肖。不肖者，比人者也。賢者，比於人者也。是故「比」五陰而一陽。五陰之爻皆言比之者，比人者也。一陽之爻獨言顯「比」者，比於人者也。比於人者，治人，比人者，治於人。今六三、上六二爻皆陰，莫能相尚。三雖居剛，而上又一卦之上；三雖體「艮」，而上乂體「坎」，是故皆有「比之」之辭，明其才德俱茂，不能以自立，相比而莫適為尊也。子曰：比之匪人，不亦傷乎？已不能以自立，所比者又非其人，禍至無日矣，不亦可傷哉？在漢建武、隗囂、公孫述、荀若、竇融者，初六當之矣。六四：外比之，貞吉。象曰：「外比」於賢，以從上也。六四上體為「坎」，下體為「坤」，以險居柔，而在上卦之下，下無其應，而承乎九五之震，故曰：「外比之，貞吉。」六二為內比，六四為外比，明矣。夫以六四之「坤」而承乎九五之「震」，其比之也固也，為其有「坎」象焉。「坎」性下流，是以戒之，守其正，然後吉也。子曰：「外比於賢，以從上也。」上者，對下之稱。四之配在初而乘乎三，二爻皆陰也。陽為賢，陰為不肖，舍不肖而比賢，四之所以為「貞吉」者歟！九五：顯比，王用三驅，失前禽，邑人不誡，吉。象曰：「顯比」之吉，位正中也。舍逆取順，「失前禽」也。「邑人不誡」，上使中也。九五，「震」也。以陽居剛而在上卦之中，應乎六二，而為五陰之所宗，故曰「顯比」。陽為明，陰為晦。「震」，東方也，日之旦也。以大中至正之道，顯然受天下之比也。誠意以待之，虛心以納之，來者不拒，去者不追，較然不欺其心，俯仰而無愧怍，此之謂「顯比」。古之聖人所以得天下者，皆是道也。故曰：「王用三驅，失前禽，邑人不誡，吉。」「王」謂五也，五體「震」，震為馬，下應乎二，所歷三爻，故有「王用三驅」之象。「禽」，謂三也，三體「艮」，「艮」為黔喙之屬。三自內比，四自外比，而三獨不順，比之匪人，故有「失前禽」之象。「邑」謂六二也，二體「坤」，「坤」為國邑，柔順中正而與五為應，故有「邑人不誡」之象。「王用三驅」，即禮所謂天子不合圍是也。三面而驅，闕其一面，順而來者取之，逆而去者舍之，古之道也。夫三面而驅，禽之逸者固多矣。聖人以為外物，任其去來而不強取之也。故曰：「子釣而不綱，弋不射宿。」成湯之祝曰：「欲左者左，欲右者右，不用命者，入吾網。」聖人之仁，蓋如此也。或曰：湯以一面而王用三驅，何也？曰：三驅，禮也。湯之一面，代虐以寬，矯枉過正，非常道也。原其設心則同矣。若夫邑人，則吾之所與同其休慼者也。方其未附也，去來逆順有所不可知。及其附也，則鞏如磐石，固如膠漆，親如父子，護如頭目，又何誡之有哉？是以大有之盛，至於易而無備；泰之盛，至於不戒以孚，然後為至也。然則聖人不取必於前禽，而取必於邑人；不取必於邑人，而取必於吾身。使吾德可比，則邑人不誡。邑人不誡，則前禽安往哉？以此顯比，可謂吉矣。子曰：顯比之吉，位正中也。舍逆取順，失前禽也。邑人不誡，上使中也。書曰：「爾身克正，罔敢不正。民心罔中，為爾之中。」上使中之義也。夫六二雖居中履正，苟無九五之君，將不能保其正矣。上之所使，不其然歟？鄭康成曰：「舍而去之不射，走而往者順而射。」王弼亦曰：禽走來趨己則舍之，背己而走，則取之。既違經旨，且非事情。又曰：可以為上之使，非為上之道。失之遠矣。王氏明象曰：古者田獵，驅禽獸於所聚之野而射之，三驅而止，未詳所出，亦恐不近人情。上六，比之無首，兇。象曰：「比之無首」，無所終也。上六，坎也，以陰居柔，而在一卦之上，下無其應，而乘乎九五之震，故曰：「比之無首」。上六以柔乘剛，而不順九五，而反與六三為比者也。小人群居，莫適為首，故曰「兇」。兩貴不能以相事，兩賤不能以相使，「比」而「無首」，「兇」不亦宜乎？「乾」之上九，「無首」而「吉」；比之上六，「無首」而「兇」。學者觀之，思過半矣。子曰：比之無首，無所終也。夫以六三「比之匪人」，固可以為兇矣，猶然不繫以兇咎之辭者，其逆順未可知也。使其幡然從天下之所歸往，孰能御之哉？至於上六，卦之終也，而卒於「無首」，其兇成矣。此所謂初辭擬之，卒成之終者歟？曰：上之於三，既非其配，而切近於九五，烏知其不從五而反比於三與？曰：為其後之故也。方比之時，一陽在上，六二自內而比之，六四自外而比之，初六自遠而比之。唯六三、上六各居一卦之上，皆有雄長之心，是以相與為比而至於後。夫所謂天下後服者先亡矣，而況於近而不相得乎？所以然者，九五震也，上六坎也，六三艮也，自以皆得乾之一體，是以不汲汲而從五也。或曰：「六四之坎也，而比之，何哉？」曰：四以陰居柔，而在上卦之終，體乎坤而成乎震，其比之也，不亦宜乎？非三、上之比也。周易經傳集解卷四。",-1)])])}const f=t(r,[["render",c]]);export{_ as __pageData,f as default};
